import { BOT_PROFILES, skillForRank } from './BotProfiles';
import { createSeededRandom } from './random';
import type { BotPersonality, BotProfile, BotRank, BotSkill } from './types';

export const MIN_BOT_RATING = 600;
export const MAX_BOT_RATING = 2600;

const RANK_ORDER = ['Rookie', 'Amateur', 'Pro', 'Master', 'Legend'] as const;
const ANCHOR_RATING: Record<BotRank, number> = { Rookie: 700, Amateur: 1000, Pro: 1300, Master: 1700, Legend: 2200 };
const RANK_THRESHOLDS: ReadonlyArray<readonly [BotRank, number]> = [
  ['Legend', 1950],
  ['Master', 1500],
  ['Pro', 1150],
  ['Amateur', 880],
];
const PERSONALITIES: readonly BotPersonality[] = ['balanced', 'careful', 'bold', 'trickster'];

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));
const lerp = (from: number, to: number, t: number): number => from + (to - from) * t;
const clampRating = (rating: number): number => clamp(rating, MIN_BOT_RATING, MAX_BOT_RATING);

export function rankForRating(rating: number): BotRank {
  for (const [rank, threshold] of RANK_THRESHOLDS) {
    if (rating >= threshold) return rank;
  }
  return 'Rookie';
}

/** Linear blend between rank anchors, clamped so extrapolation stays playable. */
function blendSkill(low: BotSkill, high: BotSkill, t: number): BotSkill {
  return {
    aimError: clamp(lerp(low.aimError, high.aimError, t), 0.012, 0.34),
    powerError: clamp(lerp(low.powerError, high.powerError, t), 0.012, 0.3),
    simulationSamples: Math.round(clamp(lerp(low.simulationSamples, high.simulationSamples, t), 30, 140)),
    riskTolerance: clamp(lerp(low.riskTolerance, high.riskTolerance, t), 0.05, 1),
    shortcutAwareness: clamp(lerp(low.shortcutAwareness, high.shortcutAwareness, t), 0, 1),
    planningDepth: Math.round(clamp(lerp(low.planningDepth, high.planningDepth, t), 1, 3)),
  };
}

function applyPersonality(skill: BotSkill, personality: BotPersonality): BotSkill {
  const riskScale = personality === 'careful' ? 0.82 : personality === 'bold' ? 1.16 : personality === 'trickster' ? 1.08 : 1;
  const shortcutScale = personality === 'trickster' ? 1.15 : personality === 'careful' ? 0.9 : 1;
  return {
    ...skill,
    riskTolerance: clamp(skill.riskTolerance * riskScale, 0.05, 1),
    shortcutAwareness: clamp(skill.shortcutAwareness * shortcutScale, 0, 1),
  };
}

/** Smooth rating -> skill mapping so AI difficulty tracks the lobby rating continuously. */
export function skillForRating(rating: number): BotSkill {
  const target = clampRating(rating);
  let lowRank: BotRank = 'Rookie';
  let highRank: BotRank = 'Amateur';
  for (let index = 0; index < RANK_ORDER.length - 1; index += 1) {
    const low = RANK_ORDER[index];
    const high = RANK_ORDER[index + 1];
    if (!low || !high) continue;
    lowRank = low;
    highRank = high;
    if (target < ANCHOR_RATING[high]) break;
  }
  const lowRating = ANCHOR_RATING[lowRank];
  const highRating = ANCHOR_RATING[highRank];
  const t = (target - lowRating) / (highRating - lowRating);
  return blendSkill(skillForRank(lowRank), skillForRank(highRank), t);
}

function personalityForRating(rating: number): BotPersonality {
  const index = Math.abs(Math.round(rating)) % PERSONALITIES.length;
  return PERSONALITIES[index] ?? 'balanced';
}

export interface SyntheticBotOptions {
  id?: string;
  displayName?: string;
  personality?: BotPersonality;
}

/** Builds an opponent whose skill comes from a rating instead of a fixed rank. */
export function botProfileForRating(rating: number, options: SyntheticBotOptions = {}): BotProfile {
  const target = Math.round(clampRating(rating));
  const rank = rankForRating(target);
  const personality = options.personality ?? personalityForRating(target);
  return {
    id: options.id ?? `bot-r${target}`,
    displayName: options.displayName ?? `${rank} ${target}`,
    rank,
    rating: target,
    personality,
    skill: applyPersonality(skillForRating(target), personality),
  };
}

/** Nudges an existing bot toward a target rating; blend 0 keeps it, 1 fully matches. */
export function tuneProfileToRating(profile: BotProfile, targetRating: number, blend = 1): BotProfile {
  const t = clamp(blend, 0, 1);
  const target = clampRating(targetRating);
  const rating = Math.round(lerp(profile.rating, target, t));
  return {
    ...profile,
    rating,
    rank: rankForRating(rating),
    skill: blendSkill(profile.skill, applyPersonality(skillForRating(target), profile.personality), t),
  };
}

export interface BotSelectionOptions {
  seed?: number | string;
  spread?: number;
  exclude?: readonly string[];
  tuneBlend?: number;
}

/** Deterministic opponent field around a rating; synthesises extra bots for big lobbies. */
export function selectBotOpponents(targetRating: number, count: number, options: BotSelectionOptions = {}): BotProfile[] {
  const wanted = Math.max(0, Math.floor(count));
  if (wanted === 0) return [];
  const spread = options.spread ?? 160;
  const exclude = new Set(options.exclude ?? []);
  const random = createSeededRandom(options.seed ?? `field:${Math.round(targetRating)}:${wanted}`);
  const ranked = BOT_PROFILES
    .filter((profile) => !exclude.has(profile.id))
    .map((profile, index) => ({
      profile,
      index,
      weight: Math.abs(profile.rating + (random() - 0.5) * 2 * spread - targetRating),
    }))
    .sort((a, b) => (a.weight - b.weight) || (a.index - b.index));

  const chosen: BotProfile[] = ranked.slice(0, wanted).map((entry) => entry.profile);
  let extra = 0;
  while (chosen.length < wanted) {
    extra += 1;
    const offset = (extra % 2 === 0 ? 1 : -1) * Math.ceil(extra / 2) * 60;
    chosen.push(botProfileForRating(targetRating + offset, { id: `bot-field-${extra}` }));
  }

  const blend = options.tuneBlend ?? 0;
  const field = blend > 0 ? chosen.map((profile) => tuneProfileToRating(profile, targetRating, blend)) : chosen;
  return field.slice().sort((a, b) => b.rating - a.rating);
}
